import AppKit
import XCTest
@testable import Cotabby

/// Tests for the on-demand clipboard description used as optional prompt context.
///
/// Every case writes to a uniquely named private pasteboard, never `NSPasteboard.general`, so the
/// user's real clipboard is untouched. What is pinned: text wins and is trimmed, blank text is not
/// context, images are summarized by format and pixel size rather than passed through, and a copy
/// marked concealed, transient, or auto-generated (including Cotabby's own paste insert) is skipped.
@MainActor
final class ClipboardContextProviderTests: XCTestCase {

    private var pasteboard: NSPasteboard!

    override func setUp() {
        super.setUp()
        pasteboard = NSPasteboard(name: NSPasteboard.Name("com.cotabby.tests.clipboard.\(UUID().uuidString)"))
        pasteboard.clearContents()
    }

    override func tearDown() {
        pasteboard.releaseGlobally()
        pasteboard = nil
        super.tearDown()
    }

    private func makeProvider() -> ClipboardContextProvider {
        TestLifetime.retain(ClipboardContextProvider(pasteboard: pasteboard))
    }

    private func pngData(width: Int, height: Int) throws -> Data {
        let bitmap = try XCTUnwrap(NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: width,
            pixelsHigh: height,
            bitsPerSample: 8,
            samplesPerPixel: 4,
            hasAlpha: true,
            isPlanar: false,
            colorSpaceName: .deviceRGB,
            bytesPerRow: 0,
            bitsPerPixel: 0
        ))
        return try XCTUnwrap(bitmap.representation(using: .png, properties: [:]))
    }

    func test_emptyPasteboardHasNoContext() {
        XCTAssertNil(makeProvider().currentContext())
    }

    func test_textIsTrimmed() {
        pasteboard.setString("  \n Quarterly budget draft \n\t", forType: .string)

        XCTAssertEqual(makeProvider().currentContext(), "Quarterly budget draft")
    }

    func test_whitespaceOnlyTextIsNotContext() {
        pasteboard.setString(" \n\t ", forType: .string)

        XCTAssertNil(makeProvider().currentContext())
    }

    func test_imageIsSummarizedByFormatAndPixelSize() throws {
        pasteboard.setData(try pngData(width: 4, height: 3), forType: .png)

        XCTAssertEqual(makeProvider().currentContext(), "Image (PNG, 4x3 px)")
    }

    func test_textTakesPrecedenceOverAnImage() throws {
        pasteboard.declareTypes([.string, .png], owner: nil)
        pasteboard.setString("caption", forType: .string)
        pasteboard.setData(try pngData(width: 4, height: 3), forType: .png)

        XCTAssertEqual(makeProvider().currentContext(), "caption")
    }

    private func writeMarked(_ text: String, marker: String) {
        let markerType = NSPasteboard.PasteboardType(marker)
        pasteboard.declareTypes([.string, markerType], owner: nil)
        pasteboard.setString(text, forType: .string)
        pasteboard.setData(Data(), forType: markerType)
    }

    /// Password managers mark a copied credential concealed; it must never become prompt context.
    func test_concealedCopyIsNotContext() {
        writeMarked("hunter2-correct-horse", marker: "org.nspasteboard.ConcealedType")

        XCTAssertNil(makeProvider().currentContext())
    }

    func test_transientAndAutoGeneratedCopiesAreNotContext() {
        for marker in ["org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType"] {
            writeMarked("one-time code 482913", marker: marker)

            XCTAssertNil(makeProvider().currentContext(), marker)
        }
    }

    /// The marker hides the whole copy, not just its text form.
    func test_concealedImageIsNotContext() throws {
        let markerType = NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType")
        pasteboard.declareTypes([.png, markerType], owner: nil)
        pasteboard.setData(try pngData(width: 4, height: 3), forType: .png)
        pasteboard.setData(Data(), forType: markerType)

        XCTAssertNil(makeProvider().currentContext())
    }

    /// The completion the paste insert puts on the pasteboard carries the markers clipboard managers
    /// look for, and Cotabby's own reader skips it instead of treating it as a user copy.
    func test_pasteInsertCompletionIsMarkedAndSkipped() {
        pasteboard.clearContents()
        XCTAssertTrue(pasteboard.writeObjects([SuggestionInserter.completionPasteboardItem(for: "the rest of it")]))

        let types = (pasteboard.types ?? []).map(\.rawValue)
        XCTAssertTrue(types.contains("org.nspasteboard.TransientType"))
        XCTAssertTrue(types.contains("org.nspasteboard.ConcealedType"))
        XCTAssertEqual(pasteboard.string(forType: .string), "the rest of it")
        XCTAssertNil(makeProvider().currentContext())
    }

    /// The coordinator compares change counts to notice a new copy without reading contents.
    func test_changeCountTracksThePasteboard() {
        let provider = makeProvider()
        let before = provider.currentChangeCount

        pasteboard.clearContents()
        pasteboard.setString("new copy", forType: .string)

        XCTAssertEqual(provider.currentChangeCount, pasteboard.changeCount)
        XCTAssertGreaterThan(provider.currentChangeCount, before)
    }
}
